    const expected = "bvh";
    const s = "yes";
    const actual = try encode(testing.allocator, s);
    defer testing.allocator.free(actual);
    try testing.expectEqualStrings(expected, actual);
}

test "encode no" {
    const expected = "ml";
    const s = "no";
    const actual = try encode(testing.allocator, s);
    defer testing.allocator.free(actual);
    try testing.expectEqualStrings(expected, actual);
}

test "encode omg" {
    const expected = "lnt";
    const s = "OMG";
    const actual = try encode(testing.allocator, s);
    defer testing.allocator.free(actual);
    try testing.expectEqualStrings(expected, actual);
}

test "encode spaces" {
    const expected = "lnt";
    const s = "O M G";
    const actual = try encode(testing.allocator, s);
    defer testing.allocator.free(actual);
    try testing.expectEqualStrings(expected, actual);
